select id, store_name, dense_rank() over (partition by region, city order by sqft desc) as sqft_dense_rank, avg(sqft) over (partition by region) as region_avg_sqft, sum(sqft) over (partition by city, region order by sqft, id rows between unbounded preceding and current row) as running_sqft, ntile(3) over (partition by city, region order by sqft, id) as sqft_bucket, min(sqft) over (partition by city) as city_min_sqft from stores
